-- Royal Travel Platform PostgreSQL schema v0.1 (reviewable foundation, not finance sign-off)
-- Uses existing Laravel users(id BIGINT). All Royal-owned tables use rt_ prefix.
CREATE TABLE rt_companies (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legal_name varchar(255) NOT NULL, display_name varchar(255), status varchar(32) NOT NULL DEFAULT 'pending', registration_no varchar(120), tax_no varchar(120), country_code char(2), preferred_locale varchar(2) NOT NULL DEFAULT 'en', account_currency char(3) NOT NULL DEFAULT 'USD', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rt_companies_locale_ck CHECK(preferred_locale IN ('ar','en'))
);
CREATE TABLE rt_company_memberships (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES rt_companies(id) ON DELETE RESTRICT, user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, role_code varchar(64) NOT NULL, status varchar(24) NOT NULL DEFAULT 'pending', approved_by bigint REFERENCES users(id) ON DELETE RESTRICT, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,user_id)
);
CREATE INDEX rt_company_memberships_user_idx ON rt_company_memberships(user_id,status);
CREATE TABLE rt_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(80) NOT NULL UNIQUE, portal varchar(12) NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rt_roles_portal_ck CHECK(portal IN ('admin','b2b','b2c','system')));
CREATE TABLE rt_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(120) NOT NULL UNIQUE, description text);
CREATE TABLE rt_role_permissions (role_id uuid NOT NULL REFERENCES rt_roles(id) ON DELETE RESTRICT, permission_id uuid NOT NULL REFERENCES rt_permissions(id) ON DELETE RESTRICT, PRIMARY KEY(role_id,permission_id));
CREATE TABLE rt_user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, role_id uuid NOT NULL REFERENCES rt_roles(id) ON DELETE RESTRICT, company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX rt_user_roles_scope_unique ON rt_user_roles(user_id,role_id,COALESCE(company_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE TABLE rt_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, uploaded_by bigint REFERENCES users(id) ON DELETE RESTRICT, disk varchar(32) NOT NULL, path text NOT NULL, original_name varchar(255), mime_type varchar(120), byte_size bigint NOT NULL CHECK(byte_size>=0), visibility varchar(12) NOT NULL DEFAULT 'private', checksum_sha256 char(64), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(disk,path), CHECK(visibility IN ('private','public')));
CREATE TABLE rt_company_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES rt_companies(id) ON DELETE RESTRICT, file_id uuid NOT NULL REFERENCES rt_files(id) ON DELETE RESTRICT, document_type varchar(80) NOT NULL, review_status varchar(24) NOT NULL DEFAULT 'pending', reviewed_by bigint REFERENCES users(id) ON DELETE RESTRICT, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,file_id));
